contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive contract and assert a property that holds on original C but is violated if onlyOwner requires msg.sender == address(0)
    function run(uint funding) public payable {
        // require this test contract has enough ETH to fund c
        require(address(this).balance >= funding);
        // send funds to c via fallback to increase its balance and depositsCount
        address(c).call{value: funding}("");

        // precondition: c has positive balance
        require(address(c).balance >= funding && funding > 0);

        // Attempt withdrawAll from this contract: since this contract is the owner for original C,
        // the call should succeed and reduce c's balance to 0. In the mutant it will revert.
        c.withdrawAll();

        // Observe c balance. On original C this contract is owner so withdrawAll transfers all funds out.
        // Assert that c's balance is now zero.
        assert(address(c).balance == 0);
    }

    // Allow contract to receive ETH for funding the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: test for any caller
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // General rule: if this contract is the owner, withdrawAll must not revert.
        // We cannot read owner's storage directly, so we express the rule via behavior:
        // If calling withdrawAll from this contract would succeed on the original,
        // then it must not revert here. Since on the original the deployer of C is owner,
        // deploying InvMutTest from that same address and passing c will make this contract
        // the owner only if c.owner() == address(this). We therefore require that when
        // c.owner() == address(this) the call does not revert.
        assert(!(c.owner() == address(this)) || reverted == false);
    }
    receive() external payable { }
}

