pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker address (as an EOA) and an amount to fund the contract
    function testFuzz_property(address attacker, uint256 funding) public {
        // keep funding in a reasonable wide range but non-zero
        funding = bound(funding, 1, 1 ether);
        // ensure attacker is not the deployer/owner
        vm.assume(attacker != address(this));

        // fund the contract so withdrawAll has a non-zero effect
        vm.deal(address(this), funding);
        // send ETH into c by invoking fallback (send via call)
        // as the owner (setUp deployer) we can send directly
        (bool sent,) = address(c).call{value: funding}("");
        require(sent);
        // record balance before attacker tries withdrawAll
        uint256 before = address(c).balance;

        // attacker attempts to call withdrawAll
        vm.deal(attacker, 1 wei); // ensure attacker has some balance for tx
        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call: For the correct contract, only the owner can withdraw, so
        // a non-owner attacker MUST NOT be able to reduce the contract balance.
        // We assert that if the caller was not the owner, the contract balance did not decrease.
        // This is a universal property the reference satisfies for all inputs; the mutant
        // (which removes onlyOwner) will allow some attacker + funding to make the balance drop,
        // causing this assertion to fail for those inputs.
        if (attacker != address(this)) {
            assertTrue(address(c).balance >= before);
        } else {
            // if attacker==owner (rare due to vm.assume) then owner legitimately can withdraw
            // just assert consistency: balance is <= before
            assertTrue(address(c).balance <= before);
        }
    }
}

